import pandas as pd
import matplotlib.pyplot as plt
from statsmodels.tsa.seasonal import seasonal_decompose

def task_func(df, freq='D', decomposition_model='multiplicative'):
    if not isinstance(df, pd.DataFrame):
        raise ValueError("If 'df' is not a DataFrame, lacks required columns, or contains invalid data types.")
    if 'value' not in df.columns:
        raise ValueError("If 'df' is not a DataFrame, lacks required columns, or contains invalid data types.")
    if not pd.api.types.is_numeric_dtype(df['value']):
        raise ValueError("If 'df' is not a DataFrame, lacks required columns, or contains invalid data types.")
    if df['value'].isna().any() or not df['value'].map(pd.notna).all():
        raise ValueError("If 'df' is not a DataFrame, lacks required columns, or contains invalid data types.")

    try:
        offset = pd.tseries.frequencies.to_offset(freq)
        period = pd.tseries.frequencies.freq_to_period(offset.freqstr)
    except Exception as exc:
        raise ValueError("If 'freq' is not a valid frequency string.") from exc

    if decomposition_model not in ('additive', 'multiplicative'):
        raise ValueError("If 'decomposition_model' is not 'additive' or 'multiplicative'.")

    series = df['value'].copy()

    if isinstance(df.index, pd.DatetimeIndex):
        series = series.asfreq(freq)

    if series.isna().any():
        raise ValueError("If 'df' is not a DataFrame, lacks required columns, or contains invalid data types.")

    if decomposition_model == 'multiplicative' and (series <= 0).any():
        raise ValueError("If 'df' is not a DataFrame, lacks required columns, or contains invalid data types.")

    result = seasonal_decompose(series, model=decomposition_model, period=period)

    fig = result.plot()
    ax = fig.axes[0] if fig.axes else plt.gca()

    return result, ax
